type BrowserRunLifecycleEvent =
  'load' | 'domcontentloaded' | 'networkidle0' | 'networkidle2';

type BrowserRunResourceType =
  | 'document'
  | 'stylesheet'
  | 'image'
  | 'media'
  | 'font'
  | 'script'
  | 'texttrack'
  | 'xhr'
  | 'fetch'
  | 'prefetch'
  | 'eventsource'
  | 'websocket'
  | 'manifest'
  | 'signedexchange'
  | 'ping'
  | 'cspviolationreport'
  | 'preflight'
  | 'other';

/** Options fields shared by all quick actions. */
interface BrowserRunBaseOptions {
  /** Adds \`<script>\` tags into the page with the desired URL or content.
   * @see https://pptr.dev/api/puppeteer.frameaddscripttagoptions
   */
  addScriptTag?: Array<{
    content?: string;
    url?: string;
    type?: string;
    id?: string;
  }>;
  /** Adds \`<link rel="stylesheet">\` or \`<style>\` tags into the page.
   * @see https://pptr.dev/api/puppeteer.frameaddstyletagoptions
   */
  addStyleTag?: Array<{ content?: string; url?: string }>;
  /** Provide credentials for HTTP authentication. @see https://pptr.dev/api/puppeteer.credentials */
  authenticate?: { username: string; password: string };
  /** Set cookies before navigating. @see https://pptr.dev/api/puppeteer.cookieparam */
  cookies?: Array<{
    name: string;
    value: string;
    url?: string;
    domain?: string;
    path?: string;
    secure?: boolean;
    httpOnly?: boolean;
    sameSite?: 'Strict' | 'Lax' | 'None';
    expires?: number;
    priority?: 'Low' | 'Medium' | 'High';
    sameParty?: boolean;
    sourceScheme?: 'Unset' | 'NonSecure' | 'Secure';
    sourcePort?: number;
    partitionKey?: string;
  }>;
  /** Emulate a specific CSS media type (e.g. \`"screen"\`, \`"print"\`). */
  emulateMediaType?: string;
  /** Navigation options. @see https://pptr.dev/api/puppeteer.gotooptions */
  gotoOptions?: {
    /** Navigation timeout in milliseconds (max 60 000). @default 30000 */
    timeout?: number;
    /** When to consider navigation complete. @default "domcontentloaded" */
    waitUntil?: BrowserRunLifecycleEvent | BrowserRunLifecycleEvent[];
    referer?: string;
    referrerPolicy?: string;
  };
  /** Block requests matching these regex patterns. Mutually exclusive with \`allowRequestPattern\`. */
  rejectRequestPattern?: string[];
  /** Only allow requests matching these regex patterns. Mutually exclusive with \`rejectRequestPattern\`. */
  allowRequestPattern?: string[];
  /** Block requests of these resource types. Mutually exclusive with \`allowResourceTypes\`. */
  rejectResourceTypes?: BrowserRunResourceType[];
  /** Only allow requests of these resource types. Mutually exclusive with \`rejectResourceTypes\`. */
  allowResourceTypes?: BrowserRunResourceType[];
  /** Additional HTTP headers sent with every request. */
  setExtraHTTPHeaders?: Record<string, string>;
  /** Whether JavaScript is enabled on the page. */
  setJavaScriptEnabled?: boolean;
  /** Override the default user agent string.
   * @default "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36"
   * */
  userAgent?: string;
  /** Set the browser viewport size.
   * @see https://pptr.dev/api/puppeteer.viewport
   * @default {width:1920,height:1080}
   * */
  viewport?: {
    width: number;
    height: number;
    deviceScaleFactor?: number;
    isMobile?: boolean;
    isLandscape?: boolean;
    hasTouch?: boolean;
  };
  /** Wait for a CSS selector to appear in the page before proceeding.
   * @see https://pptr.dev/api/puppeteer.waitforselectoroptions
   */
  waitForSelector?: {
    selector: string;
    hidden?: true;
    visible?: true;
    /** Timeout in milliseconds. Max 120000 */
    timeout?: number;
  };
  /** Wait for a fixed delay in milliseconds before proceeding. Max 120000 */
  waitForTimeout?: number;
  /** When true, continue on best-effort when awaited events fail or timeout. */
  bestAttempt?: boolean;
  /** Maximum duration in milliseconds for the browser action after page load. Max 120000 */
  actionTimeout?: number;
  /** Cache time to live in seconds (0-86400). Set to 0 to disable.
   * @default 5
   */
  cacheTTL?: number;
}

/** Backend selection for quick actions. */
interface BrowserRunAlternateBackendOptions {
  /** Render with an alternate browser backend instead of the default one. */
  browser?: 'kitesurf';
}

/** Common options shared by all quick actions. Exactly one of \`url\` or \`html\` must be provided.*/
type BrowserRunCommonOptions = BrowserRunBaseOptions &
  BrowserRunAlternateBackendOptions &
  (
    | {
        /** URL to navigate to, e.g. \`"https://example.com"\`. */
        url: string;
      }
    | {
        /** Set the HTML content of the page directly. */
        html: string;
      }
  );

type BrowserRunPuppeteerScreenshotOptions = {
  /** @default "png" */
  type?: 'png' | 'jpeg' | 'webp';
  /** @default "binary" */
  encoding?: 'binary' | 'base64';
  quality?: number;
  fullPage?: boolean;
  clip?: {
    x: number;
    y: number;
    width: number;
    height: number;
    scale?: number;
  };
  omitBackground?: boolean;
  optimizeForSpeed?: boolean;
  captureBeyondViewport?: boolean;
  fromSurface?: boolean;
};

type BrowserRunScreenshotOptions = BrowserRunCommonOptions & {
  /** CSS selector of the element to screenshot. */
  selector?: string;
  /** When true, scroll the entire page before taking the screenshot. */
  scrollPage?: boolean;
  /** @see https://pptr.dev/api/puppeteer.screenshotoptions */
  screenshotOptions?: BrowserRunPuppeteerScreenshotOptions;
};

type BrowserRunPDFOptions = BrowserRunCommonOptions & {
  /** @see https://pptr.dev/api/puppeteer.pdfoptions */
  pdfOptions?: {
    /** @default 1 */
    scale?: number;
    /** @default false */
    displayHeaderFooter?: boolean;
    headerTemplate?: string;
    footerTemplate?: string;
    /** @default false */
    printBackground?: boolean;
    /** @default false */
    landscape?: boolean;
    pageRanges?: string;
    /** @default "letter" */
    format?:
      | 'letter'
      | 'legal'
      | 'tabloid'
      | 'ledger'
      | 'a0'
      | 'a1'
      | 'a2'
      | 'a3'
      | 'a4'
      | 'a5'
      | 'a6';
    width?: string | number;
    height?: string | number;
    /** @default false */
    preferCSSPageSize?: boolean;
    margin?: {
      top?: string | number;
      right?: string | number;
      bottom?: string | number;
      left?: string | number;
    };
    /** @default false */
    omitBackground?: boolean;
    /** @default true */
    tagged?: boolean;
    /** @default false */
    outline?: boolean;
    /** @default 30000 */
    timeout?: number;
  };
};

type BrowserRunScrapeOptions = BrowserRunCommonOptions & {
  /** CSS selectors to scrape. At least one element is required. */
  elements: Array<{ selector: string }>;
};

type BrowserRunLinksOptions = BrowserRunCommonOptions & {
  /** When true, only return links that are visible on the page. @default false */
  visibleLinksOnly?: boolean;
  /** When true, exclude links pointing to external domains. @default false */
  excludeExternalLinks?: boolean;
};

type BrowserRunSnapshotFormat =
  'content' | 'screenshot' | 'markdown' | 'accessibilityTree';

type BrowserRunSnapshotOptions = BrowserRunCommonOptions & {
  /** Which representations of the page to return. At least two distinct formats
   * are required; request a single format from its dedicated action instead.
   * @default ["content","screenshot"]
   */
  formats?: BrowserRunSnapshotFormat[];
  /** @see https://pptr.dev/api/puppeteer.screenshotoptions */
  screenshotOptions?: Omit<BrowserRunPuppeteerScreenshotOptions, 'encoding'>;
};

/** Options for the \`accessibilityTree\` quick action. */
type BrowserRunAccessibilityTreeOptions = BrowserRunCommonOptions & {
  /** When true, prune nodes that carry no semantic meaning, such as generic
   * containers. Defaults to true, or to false when \`root\` is set so that the
   * requested subtree is returned as-is.
   */
  interestingOnly?: boolean;
  /** CSS selector limiting the tree to the matching element's subtree.
   * A selector that matches nothing yields \`accessibilityTree: null\` with
   * HTTP 200; a malformed selector is an error.
   */
  root?: string;
};

interface BrowserRunJsonBaseOptions {
  /** Custom AI models to try in order. Max 3. Falls back to next on error. */
  custom_ai?: Array<{
    /** Model ID in \`<provider>/<model_name>\` format, e.g. \`"workers-ai/@cf/meta/llama-3.3-70b-instruct-fp8-fast"\`. */
    model: string;
    /** Bearer token. Not needed for workers-ai models. */
    authorization?: string;
  }>;
}

/**
 * Options for the \`json\` quick action.
 * At least one of \`prompt\` or \`response_format\` must be provided.
 */
type BrowserRunJsonOptions = BrowserRunCommonOptions &
  BrowserRunJsonBaseOptions &
  (
    | {
        /** Natural-language prompt describing what data to extract. */
        prompt: string;
        /** Structured output schema for the AI model. @see https://developers.cloudflare.com/workers-ai/json-mode/ */
        response_format?: AiTextGenerationResponseFormat;
      }
    | {
        /** Natural-language prompt describing what data to extract. */
        prompt?: string;
        /** Structured output schema for the AI model. @see https://developers.cloudflare.com/workers-ai/json-mode/ */
        response_format: AiTextGenerationResponseFormat;
      }
  );

type BrowserRunContentOptions = BrowserRunCommonOptions;
type BrowserRunMarkdownOptions = BrowserRunCommonOptions;

type BrowserRunRedirectHop = {
  /** URL that returned the redirect. */
  url: string;
  /** HTTP status of the redirect. */
  status: number;
  /** Redirect response headers, including \`location\`. */
  headers: Record<string, string>;
};

type BrowserRunResponseMeta = {
  /** HTTP status code of the rendered page */
  status: number;
  /** Page title */
  title: string;
  /** Origin response headers, lowercased. Repeated headers are joined with a newline. Credential and transport-only headers that do not survive rendering are omitted. */
  headers?: Record<string, string>;
  /** URL that served the response, after any redirects the browser followed. */
  finalUrl?: string;
  /** HTTP redirects followed to reach \`finalUrl\`, oldest first. Omitted for direct navigation and for client-side redirects such as meta refresh. An empty array means redirects occurred but their intermediate responses could not be read. */
  redirectChain?: BrowserRunRedirectHop[];
};

/**
 * A node in the page's accessibility tree, as exposed to assistive technology.
 * \`role\` is the only field always present; the rest are populated when the
 * underlying element defines them.
 * @see https://pptr.dev/api/puppeteer.serializedaxnode
 */
interface BrowserRunSerializedAXNode {
  /** The ARIA role, e.g. \`"button"\`, \`"heading"\`, \`"RootWebArea"\`. */
  role: string;
  /** The \`aria-autocomplete\` value. */
  autocomplete?: string;
  /** Checked state of a checkbox, radio, or menu item. */
  checked?: boolean | 'mixed';
  /** Accessible description, typically from \`aria-describedby\` or \`title\`. */
  description?: string;
  disabled?: boolean;
  expanded?: boolean;
  /** Whether the element currently holds keyboard focus. */
  focused?: boolean;
  /** The kind of popup the element triggers, e.g. \`"menu"\`, \`"dialog"\`. */
  haspopup?: string;
  /** The \`aria-invalid\` value. */
  invalid?: string;
  /** Keyboard shortcuts bound to the element, from \`aria-keyshortcuts\`. */
  keyshortcuts?: string;
  /** Hierarchical level, e.g. the heading level of an \`<h2>\`. */
  level?: number;
  /** Whether the element is a modal dialog. */
  modal?: boolean;
  /** Whether a text input accepts multiple lines. */
  multiline?: boolean;
  /** Whether more than one option can be selected. */
  multiselectable?: boolean;
  /** Accessible name, e.g. a button's label or an image's alt text. */
  name?: string;
  orientation?: string;
  /** Pressed state of a toggle button. */
  pressed?: boolean | 'mixed';
  readonly?: boolean;
  required?: boolean;
  /** Author-supplied role description, from \`aria-roledescription\`. */
  roledescription?: string;
  selected?: boolean;
  /** Current value of an input or range element. */
  value?: string | number;
  valuemax?: number;
  valuemin?: number;
  /** Human-readable form of \`value\`, from \`aria-valuetext\`. */
  valuetext?: string;
  /** Child nodes. Absent for leaf nodes. */
  children?: BrowserRunSerializedAXNode[];
}

/** Success response for \`content\` action. */
type BrowserRunContentSuccessResponse = {
  success: true;
  /** Extracted HTML content */
  result: string;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`links\` action. */
type BrowserRunLinksSuccessResponse = {
  success: true;
  /** Extracted links */
  result: string[];
  meta: BrowserRunResponseMeta;
};

/** Success response for \`scrape\` action. */
type BrowserRunScrapeSuccessResponse = {
  success: true;
  result: Array<{
    /** The CSS selector used to find elements. */
    selector: string;
    /** Array of elements matching the selector. */
    results: Array<{
      /** Outer HTML of the element. */
      html: string;
      /** Text content of the element. */
      text: string;
      /** Width of the element in pixels. */
      width: number;
      /** Height of the element in pixels. */
      height: number;
      /** Top position of the element relative to the viewport in pixels. */
      top: number;
      /** Left position of the element relative to the viewport in pixels. */
      left: number;
      /** Array of HTML attributes on the element. */
      attributes: Array<{
        /** Attribute name. */
        name: string;
        /** Attribute value. */
        value: string;
      }>;
    }>;
  }>;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`snapshot\` action. Each field is present only when the
 * corresponding entry was requested in \`formats\`.
 */
type BrowserRunSnapshotSuccessResponse = {
  success: true;
  result: {
    /** HTML content of the page. */
    content?: string;
    /** Base64-encoded screenshot image. */
    screenshot?: string;
    /** Markdown content. Prefixed with YAML frontmatter (e.g. \`title\`) when the
     * page provides that metadata.
     */
    markdown?: string;
    /** Root of the page's accessibility tree. */
    accessibilityTree?: BrowserRunSerializedAXNode;
  };
  meta: BrowserRunResponseMeta;
};

/** Success response for \`accessibilityTree\` action. */
type BrowserRunAccessibilityTreeSuccessResponse = {
  success: true;
  result: {
    /** Root of the accessibility tree, or \`null\` when \`root\` matched no element. */
    accessibilityTree: BrowserRunSerializedAXNode | null;
  };
  meta: BrowserRunResponseMeta;
};

/** Success response for \`json\` action. */
type BrowserRunJsonSuccessResponse = {
  success: true;
  /** JSON data extracted from the page using an AI model */
  result: Record<string, unknown>;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`markdown\` action. */
type BrowserRunMarkdownSuccessResponse = {
  success: true;
  /** Extracted markdown content */
  result: string;
  meta: BrowserRunResponseMeta;
};

/** Error response for BrowserRun actions. */
type BrowserRunErrorResponse = {
  success: false;
  errors: { message: string; code?: number; detail?: string; path?: string }[];
};

/** Error response for BrowserRun \`json\` action. */
type BrowserRunJsonErrorResponse = BrowserRunErrorResponse & {
  /** Raw AI response text for debugging */
  rawAiResponse?: string;
};

/** Session-scoped guardrails applied when acquiring a browser session. */
type BrowserRunAcquireGuardrails = {
  /** Domains that the browser may access. An empty list denies all domains. */
  allowedDomains?: string[];
  /** Named domain sets that the browser may access. */
  allowedDomainSets?: string[];
};

/** Options for acquiring a new browser session. */
type BrowserRunAcquireOptions = {
  /** Idle session lifetime in milliseconds. */
  keepAlive?: number;
  /** Record the browser session. */
  recording?: boolean;
  /** Geoegress hint as an ISO-3166 alpha-2 country code. */
  location?: string;
  /** Map hostnames to caller-provided Workers that handle outbound requests. */
  outboundByHost?: Record<string, Fetcher>;
  /** Session-scoped network guardrails. */
  guardrails?: BrowserRunAcquireGuardrails;
  /** Include the session's DevTools targets in the result. */
  targets?: boolean;
  /** Lifetime of target live-view URLs in milliseconds. */
  liveViewUrlExpiresInMs?: number;
};

/** Metadata returned when a browser session is acquired. */
type BrowserRunAcquireResult = {
  sessionId: string;
  targets?: BrowserRunDevToolsTarget[];
};

/** Options for connecting to an already-acquired browser session. */
type BrowserRunConnectOptions = {
  /** Connect to a specific page target instead of the browser-level CDP endpoint. */
  targetId?: string;
};

/** Connection capability returned by \`connectSession()\` and \`launch()\`. */
type BrowserRunConnection = {
  sessionId: string;
  /** A session-pinned Fetcher. Use its \`fetch()\` method for a WebSocket upgrade. */
  webSocket: Fetcher;
  targets?: BrowserRunDevToolsTarget[];
};

/** The UI mode for a live-view link. */
type BrowserRunLiveViewMode = 'devtools' | 'tab' | 'full';

/** Connection-scoped guardrails applied to a live-view link. */
type BrowserRunConnectionGuardrails = {
  mode: 'readonly';
};

/** Options for minting a live-view link. */
type BrowserRunLiveViewOptions = {
  mode?: BrowserRunLiveViewMode;
  targetId?: string;
  expiresInMs?: number;
  guardrails?: BrowserRunConnectionGuardrails;
};

/** Live-view link metadata. */
type BrowserRunLiveView = {
  webSocketDebuggerUrl: string;
  devtoolsFrontendUrl: string;
  id: string;
  options: {
    mode: BrowserRunLiveViewMode;
    guardrails?: BrowserRunConnectionGuardrails;
  };
};

/** Options for listing active browser sessions. */
type BrowserRunListSessionsOptions = {
  limit?: number;
  offset?: number;
};

/** Options for listing session history. */
type BrowserRunHistoryOptions = {
  limit?: number;
  offset?: number;
};

/** A browser session returned by the session-management methods. */
type BrowserRunSession = {
  sessionId: string;
  startTime?: number;
  endTime?: number;
  closeReason?: number;
  closeReasonText?: string;
  connectionId?: string;
  connectionStartTime?: number;
  connectionEndTime?: number;
  lastUpdated?: number;
  webSocketDebuggerUrl?: string;
  devtoolsFrontendUrl?: string;
};

/** Account browser-session and browser-time limits. */
type BrowserRunLimits = {
  activeSessions: Array<{ id: string }>;
  maxConcurrentSessions: number;
  allowedBrowserAcquisitions: number;
  timeUntilNextAllowedBrowserAcquisition: number;
  usedBrowserTimeSeconds?: number;
};

/** A browser target returned by the DevTools JSON methods. */
type BrowserRunDevToolsTarget = {
  id: string;
  type: string;
  url: string;
  title?: string;
  description?: string;
  webSocketDebuggerUrl?: string;
  devtoolsFrontendUrl?: string;
};

/** Browser and protocol version metadata. */
type BrowserRunDevToolsVersion = {
  Browser: string;
  'Protocol-Version': string;
  'User-Agent': string;
  'V8-Version': string;
  'WebKit-Version': string;
  webSocketDebuggerUrl: string;
};

/** A DevTools protocol domain. Protocol definitions may gain additional fields over time. */
interface BrowserRunDevToolsProtocolDomain extends Record<string, unknown> {
  domain: string;
  experimental?: boolean;
  dependencies?: string[];
  types?: Array<Record<string, any>>;
  commands?: Array<Record<string, any>>;
  events?: Array<Record<string, any>>;
}

/** The DevTools protocol definition. Additional protocol fields may be returned by Chrome. */
interface BrowserRunDevToolsProtocol extends Record<string, any> {
  domains: BrowserRunDevToolsProtocolDomain[];
  version?: { major: string; minor: string };
}

/** Options shared by DevTools target-listing and target-creation methods. */
type BrowserRunTargetOptions = {
  liveViewUrlExpiresInMs?: number;
};

/** Result returned by DevTools target activation and close methods. */
type BrowserRunTargetActionResult = {
  message: string;
};

/** Methods exposed by the nested \`devtools\` binding target. */
type BrowserRunDevtools = {
  getVersion(sessionId: string): Promise<BrowserRunDevToolsVersion>;
  getProtocol(sessionId: string): Promise<BrowserRunDevToolsProtocol>;
  listTargets(
    sessionId: string,
    options?: BrowserRunTargetOptions
  ): Promise<BrowserRunDevToolsTarget[]>;
  getTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunDevToolsTarget>;
  newTarget(
    sessionId: string,
    url?: string,
    options?: BrowserRunTargetOptions
  ): Promise<BrowserRunDevToolsTarget>;
  activateTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunTargetActionResult>;
  closeTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunTargetActionResult>;
};

/** Result returned when closing a browser session. */
type BrowserRunCloseSessionResult = {
  status: 'closing' | 'closed';
};

/**
 * Browser Run API binding for automating headless browsers.
 * @see https://developers.cloudflare.com/browser-run/
 */
declare abstract class BrowserRun {
  /**
   * Send a raw HTTP request to the Browser Run API.
   * Used by libraries like \`@cloudflare/puppeteer\` to acquire and connect to a browser instance.
   * @see https://developers.cloudflare.com/browser-run/
   */
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;

  /**
   * Take a screenshot of a web page.
   * @param action - Must be \`'screenshot'\`.
   * @param options - Screenshot options including viewport, selectors, and image format.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - Binary image data with \`Content-Type: image/png\`, \`image/jpeg\`, or \`image/webp\` (when \`encoding: 'binary'\`, the default)
   * - Data URI string with \`Content-Type: text/plain\` (when \`encoding: 'base64'\`)
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'screenshot',
    options: BrowserRunScreenshotOptions
  ): Promise<Response>;

  /**
   * Generate a PDF of a web page.
   * @param action - Must be \`'pdf'\`.
   * @param options - PDF generation options including page size, margins, and headers/footers.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - Binary PDF data with \`Content-Type: application/pdf\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(action: 'pdf', options: BrowserRunPDFOptions): Promise<Response>;

  /**
   * Get the HTML content of a web page.
   * @param action - Must be \`'content'\`.
   * @param options - Navigation and page interaction options.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunContentSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'content',
    options: BrowserRunContentOptions
  ): Promise<Response>;

  /**
   * Scrape elements from a web page by CSS selector.
   * @param action - Must be \`'scrape'\`.
   * @param options - Scrape options with CSS selectors for elements to extract.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunScrapeSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'scrape',
    options: BrowserRunScrapeOptions
  ): Promise<Response>;

  /**
   * Extract all links from a web page.
   * @param action - Must be \`'links'\`.
   * @param options - Options to filter visible or internal links only.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunLinksSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'links',
    options: BrowserRunLinksOptions
  ): Promise<Response>;

  /**
   * Get several representations of a web page in one request.
   * @param action - Must be \`'snapshot'\`.
   * @param options - Snapshot options including the \`formats\` to return and
   * screenshot settings (encoding is always base64).
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunSnapshotSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'snapshot',
    options: BrowserRunSnapshotOptions
  ): Promise<Response>;

  /**
   * Extract structured JSON data from a web page using AI.
   * @param action - Must be \`'json'\`.
   * @param options - JSON extraction options with prompt or response_format schema.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunJsonSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 with code \`2012\` for HTML-to-markdown conversion failures
   * - HTTP 422/500 for AI extraction failures (may include \`rawAiResponse\` field)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'json',
    options: BrowserRunJsonOptions
  ): Promise<Response>;

  /**
   * Convert a web page to Markdown.
   * @param action - Must be \`'markdown'\`.
   * @param options - Navigation and page interaction options.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunMarkdownSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 with code \`2012\` for HTML-to-markdown conversion failures
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'markdown',
    options: BrowserRunMarkdownOptions
  ): Promise<Response>;

  /**
   * Get the accessibility tree of a web page.
   * @param action - Must be \`'accessibilityTree'\`.
   * @param options - Options to scope the tree to a subtree and to control
   * whether semantically uninteresting nodes are pruned.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunAccessibilityTreeSuccessResponse\` JSON with \`Content-Type: application/json\`
   * - \`result.accessibilityTree\` is \`null\` when \`root\` matched no element
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 for a malformed \`root\` selector
   * - HTTP 500 with code \`2017\` or \`2018\` when the tree could not be built
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'accessibilityTree',
    options: BrowserRunAccessibilityTreeOptions
  ): Promise<Response>;
  /** Acquire a new browser session and return its metadata. */
  acquire(options?: BrowserRunAcquireOptions): Promise<BrowserRunAcquireResult>;

  /** Acquire a browser session and return a session-pinned WebSocket capability. */
  launch(options?: BrowserRunAcquireOptions): Promise<BrowserRunConnection>;

  /** Return a session-pinned WebSocket capability for an existing session. */
  connectSession(
    sessionId: string,
    options?: BrowserRunConnectOptions
  ): Promise<BrowserRunConnection>;

  /** Mint an authenticated live-view link for a browser session. */
  getLiveView(
    sessionId: string,
    options?: BrowserRunLiveViewOptions
  ): Promise<BrowserRunLiveView>;

  /** List the caller's active browser sessions. */
  listSessions(
    options?: BrowserRunListSessionsOptions
  ): Promise<BrowserRunSession[]>;

  /** List recent active and closed browser sessions. */
  history(options?: BrowserRunHistoryOptions): Promise<BrowserRunSession[]>;

  /** Return the caller's browser-session and browser-time limits. */
  limits(): Promise<BrowserRunLimits>;

  /** Return details for one browser session, or \`null\` when it does not exist. */
  getSession(sessionId: string): Promise<BrowserRunSession | null>;

  /** Close a browser session. */
  closeSession(sessionId: string): Promise<BrowserRunCloseSessionResult>;

  /** DevTools JSON methods exposed through one nested binding target. */
  get devtools(): BrowserRunDevtools;
}

/**
 * In addition to the properties you can set in the RequestInit dict
 * that you pass as an argument to the Request constructor, you can
 * set certain properties of a \`cf\` object to control how Cloudflare
 * features are applied to that new Request.
 *
 * Note: Currently, these properties cannot be tested in the
 * playground.
 */
interface RequestInitCfProperties extends Record<string, unknown> {
  cacheEverything?: boolean;
  /**
   * A request's cache key is what determines if two requests are
   * "the same" for caching purposes. If a request has the same cache key
   * as some previous request, then we can serve the same cached response for
   * both. (e.g. 'some-key')
   *
   * Only available for Enterprise customers.
   */
  cacheKey?: string;
  /**
   * This allows you to append additional Cache-Tag response headers
   * to the origin response without modifications to the origin server.
   * This will allow for greater control over the Purge by Cache Tag feature
   * utilizing changes only in the Workers process.
   *
   * Only available for Enterprise customers.
   */
  cacheTags?: string[];
  /**
   * Force response to be cached for a given number of seconds. (e.g. 300)
   */
  cacheTtl?: number;
  /**
   * Force response to be cached for a given number of seconds based on the Origin status code.
   * (e.g. { '200-299': 86400, '404': 1, '500-599': 0 })
   */
  cacheTtlByStatus?: Record<string, number>;
  /**
   * Controls whether Cloudflare uses range requests when fetching the response
   * from the origin.
   *
   * - \`"on"\`: enable origin range requests for this request.
   * - \`"off"\`: disable origin range requests for this request.
   */
  originRangeRequests?: "on" | "off";
  /** Controls how responses with a \`Vary\` header are cached for this request. */
  vary?: RequestInitCfPropertiesVary;
  /**
   * Explicit Cache-Control header value to set on the response stored in cache.
   * This gives full control over cache directives (e.g. 'public, max-age=3600, s-maxage=86400').
   *
   * Cannot be used together with \`cacheTtl\` or the \`cache\` request option (\`no-store\`/\`no-cache\`),
   * as these are mutually exclusive cache control mechanisms. Setting both will throw a TypeError.
   *
   * Can be used together with \`cacheTtlByStatus\`.
   */
  cacheControl?: string;
  /**
   * Whether the response should be eligible for Cache Reserve storage.
   */
  cacheReserveEligible?: boolean;
  /**
   * Whether to respect strong ETags (as opposed to weak ETags) from the origin.
   */
  respectStrongEtag?: boolean;
  /**
   * Whether to strip ETag headers from the origin response before caching.
   */
  stripEtags?: boolean;
  /**
   * Whether to strip Last-Modified headers from the origin response before caching.
   */
  stripLastModified?: boolean;
  /**
   * Whether to enable Cache Deception Armor, which protects against web cache
   * deception attacks by verifying the Content-Type matches the URL extension.
   */
  cacheDeceptionArmor?: boolean;
  /**
   * Minimum file size in bytes for a response to be eligible for Cache Reserve storage.
   */
  cacheReserveMinimumFileSize?: number;
  scrapeShield?: boolean;
  apps?: boolean;
  /**
   * Controls whether an outbound gRPC-web subrequest from this Worker is
   * converted to gRPC at the Cloudflare edge.
   *
   * - \`"passthrough"\`: forward the subrequest unchanged as gRPC-web (default).
   * - \`"convert"\`: convert the gRPC-web subrequest to gRPC at the edge.
   *
   * Provides per-request control over the same edge conversion behavior
   * gated by the \`auto_grpc_convert\` compatibility flag.
   */
  grpcWeb?: "passthrough" | "convert";
  image?: RequestInitCfPropertiesImage;
  minify?: RequestInitCfPropertiesImageMinify;
  mirage?: boolean;
  polish?: "lossy" | "lossless" | "off";
  r2?: RequestInitCfPropertiesR2;
  /**
   * Redirects the request to an alternate origin server. You can use this,
   * for example, to implement load balancing across several origins.
   * (e.g.us-east.example.com)
   *
   * Note - For security reasons, the hostname set in resolveOverride must
   * be proxied on the same Cloudflare zone of the incoming request.
   * Otherwise, the setting is ignored. CNAME hosts are allowed, so to
   * resolve to a host under a different domain or a DNS only domain first
   * declare a CNAME record within your own zone\u2019s DNS mapping to the
   * external hostname, set proxy on Cloudflare, then set resolveOverride
   * to point to that CNAME record.
   */
  resolveOverride?: string;
}

/**
 * Controls how Workers Standard Vary handles a request header listed by an
 * origin \`Vary\` response header:
 *
 * - \`"normalize"\`: normalize the request header value before it is used in the
 *   cache variance key.
 * - \`"passthrough"\`: use the raw request header value in the cache variance
 *   key.
 * - \`"bypass"\`: bypass cache when the header appears in the origin \`Vary\`
 *   response header.
 */
type RequestInitCfPropertiesVaryAction =
  | "normalize"
  | "passthrough"
  | "bypass";

/** Configuration for Workers Standard Vary support. */
interface RequestInitCfPropertiesVary {
  /** The fallback action for varied request headers not listed in \`headers\`. */
  default: RequestInitCfPropertiesVaryHeader;
  /**
   * Lowercase request header names and their Vary configuration.
   *
   * The \`accept\` header can include \`media_types\`, the \`accept-language\`
   * header can include \`languages\`, and other headers support only \`action\`.
   */
  headers?: RequestInitCfPropertiesVaryHeaders;
}

/** Common Vary behavior for a single request header. */
interface RequestInitCfPropertiesVaryHeader {
  /** How this request header contributes to cache variance. */
  action: RequestInitCfPropertiesVaryAction;
}

/** Vary behavior for the \`accept\` request header. */
interface RequestInitCfPropertiesVaryAcceptHeader
  extends RequestInitCfPropertiesVaryHeader {
  /**
   * Media types to keep when normalizing the \`Accept\` request header.
   *
   * Named \`media_types\` to match the serialized \`cf.vary\` configuration.
   */
  media_types?: string[];
}

/** Vary behavior for the \`accept-language\` request header. */
interface RequestInitCfPropertiesVaryAcceptLanguageHeader
  extends RequestInitCfPropertiesVaryHeader {
  /**
   * Language tags to keep when normalizing the \`Accept-Language\` request
   * header.
   */
  languages?: string[];
}

/**
 * Lowercase request header names and their Vary behavior.
 *
 * The index signature allows arbitrary custom request headers beyond the
 * well-known \`accept\` and \`accept-language\` specializations.
 */
interface RequestInitCfPropertiesVaryHeaders {
  accept?: RequestInitCfPropertiesVaryAcceptHeader;
  "accept-language"?: RequestInitCfPropertiesVaryAcceptLanguageHeader;
  [header: string]:
    | RequestInitCfPropertiesVaryHeader
    | RequestInitCfPropertiesVaryAcceptHeader
    | RequestInitCfPropertiesVaryAcceptLanguageHeader
    | undefined;
}

interface BasicImageTransformations {
  /**
   * Maximum width in image pixels. The value must be an integer.
   */
  width?: number;
  /**
   * Maximum height in image pixels. The value must be an integer.
   */
  height?: number;
  /**
   * When cropping with fit: "cover", this defines the side or point that should
   * be left uncropped. The value is either a string
   * "left", "right", "top", "bottom", "auto", or "center" (the default),
   * or an object {x, y} containing focal point coordinates in the original
   * image expressed as fractions ranging from 0.0 (top or left) to 1.0
   * (bottom or right), 0.5 being the center. {fit: "cover", gravity: "top"} will
   * crop bottom or left and right sides as necessary, but won\u2019t crop anything
   * from the top. {fit: "cover", gravity: {x:0.5, y:0.2}} will crop each side to
   * preserve as much as possible around a point at 20% of the height of the
   * source image.
   */
  gravity?:
    | 'face'
    | 'left'
    | 'right'
    | 'top'
    | 'bottom'
    | 'center'
    | 'auto'
    | 'entropy'
    | BasicImageTransformationsGravityCoordinates;
  /**
   * Specifies how closely the image is cropped toward detected faces when combined
   * with the gravity=face option. Accepts a valid range between 0.0 (includes as much
   * of the background as possible) and 1.0 (crops the image as closely to the face as
   * possible). The default is 0.
   */
  zoom?: number;
  /**
   * Resizing mode as a string. It affects interpretation of width and height
   * options:
   *  - scale-down: Similar to contain, but the image is never enlarged. If
   *    the image is larger than given width or height, it will be resized.
   *    Otherwise its original size will be kept.
   *  - scale-up: Similar to contain, but the image is never shrunk. If the
   *    image is smaller than the given width or height, it will be resized.
   *    Otherwise its original size will be kept.
   *  - contain: Resizes to maximum size that fits within the given width and
   *    height. If only a single dimension is given (e.g. only width), the
   *    image will be shrunk or enlarged to exactly match that dimension.
   *    Aspect ratio is always preserved.
   *  - cover: Resizes (shrinks or enlarges) to fill the entire area of width
   *    and height. If the image has an aspect ratio different from the ratio
   *    of width and height, it will be cropped to fit.
   *  - crop: The image will be shrunk and cropped to fit within the area
   *    specified by width and height. The image will not be enlarged. For images
   *    smaller than the given dimensions it's the same as scale-down. For
   *    images larger than the given dimensions, it's the same as cover.
   *    See also trim.
   *  - pad: Resizes to the maximum size that fits within the given width and
   *    height, and then fills the remaining area with a background color
   *    (white by default). Use of this mode is not recommended, as the same
   *    effect can be more efficiently achieved with the contain mode and the
   *    CSS object-fit: contain property.
   *  - squeeze: Stretches and deforms to the width and height given, even if it
   *    breaks aspect ratio
   */
  fit?:
    | "scale-down"
    | "scale-up"
    | "contain"
    | "cover"
    | "crop"
    | "pad"
    | "squeeze";
  /**
   * Allows you to trim your image. Takes dpr into account and is performed before
   * resizing or rotation.
   *
   * It can be used as:
   * - left, top, right, bottom - it will specify the number of pixels to cut
   *   off each side
   * - width, height - the width/height you'd like to end up with - can be used
   *   in combination with the properties above
   * - border - this will automatically trim the surroundings of an image based on
   *   it's color. It consists of three properties:
   *    - color: rgb or hex representation of the color you wish to trim (todo: verify the rgba bit)
   *    - tolerance: difference from color to treat as color
   *    - keep: the number of pixels of border to keep
   */
  trim?: "border" | {
    top?: number;
    bottom?: number;
    left?: number;
    right?: number;
    width?: number;
    height?: number;
    border?:
      | boolean
      | {
          color?: string;
          tolerance?: number;
          keep?: number;
        };
  };
  /**
   * Background color to add underneath the image. Applies only to images with
   * transparency (such as PNG). Accepts any CSS color (#RRGGBB, rgba(\u2026),
   * hsl(\u2026), etc.)
   */
  background?: string;
  /**
   * Flips the images horizontally, vertically, or both. Flipping is applied before
   * rotation, so if you apply flip=h,rotate=90 then the image will be flipped
   * horizontally, then rotated by 90 degrees.
   */
  flip?: 'h' | 'v' | 'hv';
  /**
   * Number of degrees (90, 180, 270) to rotate the image by. width and height
   * options refer to axes after rotation.
   */
  rotate?: 0 | 90 | 180 | 270 | 360;
  /**
   * Strength of sharpening filter to apply to the image. Floating-point
   * number between 0 (no sharpening, default) and 10 (maximum). 1.0 is a
   * recommended value for downscaled images.
   */
  sharpen?: number;
  /**
   * Radius of a blur filter (approximate gaussian). Maximum supported radius
   * is 250.
   */
  blur?: number;
  /**
   * Increase contrast by a factor. A value of 1.0 equals no change, a value of
   * 0.5 equals low contrast, and a value of 2.0 equals high contrast. 0 is
   * ignored.
   */
  contrast?: number;
  /**
   * Increase brightness by a factor. A value of 1.0 equals no change, a value
   * of 0.5 equals half brightness, and a value of 2.0 equals twice as bright.
   * 0 is ignored.
   */
  brightness?: number;
  /**
   * Increase exposure by a factor. A value of 1.0 equals no change, a value of
   * 0.5 darkens the image, and a value of 2.0 lightens the image. 0 is ignored.
   */
  gamma?: number;
  /**
   * Increase contrast by a factor. A value of 1.0 equals no change, a value of
   * 0.5 equals low contrast, and a value of 2.0 equals high contrast. 0 is
   * ignored.
   */
  saturation?: number;
  /**
   * Device Pixel Ratio. Default 1. Multiplier for width/height that makes it
   * easier to specify higher-DPI sizes in <img srcset>.
   */
  dpr?: number;
  /**
   * Adds a border around the image. The border is added after resizing. Border
   * width takes dpr into account, and can be specified either using a single
   * width property, or individually for each side.
   */
  border?:
    | {
        color: string;
        width: number;
      }
    | {
        color: string;
        top: number;
        right: number;
        bottom: number;
        left: number;
      };
  /**
   * Image segmentation using artificial intelligence models. Sets pixels not
   * within selected segment area to transparent e.g "foreground" sets every
   * background pixel as transparent.
   */
  segment?: "foreground";
  /**
   * Controls the algorithm used when an image needs to be enlarged. This
   * parameter works with any fit mode that upscales, such as \`contain\`,
   * \`cover\`, and \`scale-up\`. It has no effect when \`fit=scale-down\` or when
   * the target dimensions are smaller than the source.
   * - interpolate: Uses bicubic interpolation, which may reduce image quality.
   *   This is the default behavior when \`upscale\` is not specified.
   * - generate: Uses AI upscaling to produce sharper, more detailed results
   *   when enlarging images.
   */
  upscale?: "interpolate" | "generate";
}

interface BasicImageTransformationsGravityCoordinates {
  x?: number;
  y?: number;
  mode?: 'remainder' | 'box-center';
}

interface RequestInitCfPropertiesImageDraw extends BasicImageTransformations {
  /**
   * Absolute URL of the image file to use for the drawing. It can be any of
   * the supported file formats. For drawing of watermarks or non-rectangular
   * overlays we recommend using PNG or WebP images.
   */
  url: string;
  /**
   * Floating-point number between 0 (transparent) and 1 (opaque).
   * For example, opacity: 0.5 makes overlay semitransparent.
   */
  opacity?: number;
  /**
   * - If set to true, the overlay image will be tiled to cover the entire
   *   area. This is useful for stock-photo-like watermarks.
   * - If set to "x", the overlay image will be tiled horizontally only
   *   (form a line).
   * - If set to "y", the overlay image will be tiled vertically only
   *   (form a line).
   */
  repeat?: true | "x" | "y";
  /**
   * How to combine the foreground and backdrop pixels to create the result
   */
  composite?:
    /** Foreground drawn on top of backdrop (default) */
    | 'over'
    /** Foreground shown only where backdrop is opaque */
    | 'in'
    /** Foreground drawn on top, but clipped to the backdrop's shape */
    | 'atop'
    /** Foreground shown only where backdrop is transparent */
    | 'out'
    /** Foreground and backdrop visible only where the other is not */
    | 'xor'
    /** Foreground and backdrop channels added (brightening) */
    | 'lighter';

  /**
   * Position of the overlay image relative to a given edge. Each property is
   * an offset in pixels. 0 aligns exactly to the edge. For example, left: 10
   * positions left side of the overlay 10 pixels from the left edge of the
   * image it's drawn over. bottom: 0 aligns bottom of the overlay with bottom
   * of the background image.
   *
   * Setting both left & right, or both top & bottom is an error.
   *
   * If no position is specified, the image will be centered.
   */
  top?: number;
  left?: number;
  bottom?: number;
  right?: number;
}

interface RequestInitCfPropertiesImage extends BasicImageTransformations {
  /**
   * Quality setting from 1-100 (useful values are in 60-90 range). Lower values
   * make images look worse, but load faster. The default is 85. It applies only
   * to JPEG and WebP images. It doesn\u2019t have any effect on PNG.
   */
  quality?: number | "low" | "medium-low" | "medium-high" | "high";
  /**
   * Output format to generate. It can be:
   *  - avif: generate images in AVIF format.
   *  - webp: generate images in Google WebP format. Set quality to 100 to get
   *    the WebP-lossless format.
   *  - json: instead of generating an image, outputs information about the
   *    image, in JSON format. The JSON object will contain image size
   *    (before and after resizing), source image\u2019s MIME type, file size, etc.
   * - jpeg: generate images in JPEG format.
   * - png: generate images in PNG format.
   */
  format?: "avif" | "webp" | "json" | "jpeg" | "png" | "baseline-jpeg" | "png-force" | "svg";
  /**
   * Whether to preserve animation frames from input files. Default is true.
   * Setting it to false reduces animations to still images. This setting is
   * recommended when enlarging images or processing arbitrary user content,
   * because large GIF animations can weigh tens or even hundreds of megabytes.
   * It is also useful to set anim:false when using format:"json" to get the
   * response quicker without the number of frames.
   */
  anim?: boolean;
  /**
   * What EXIF data should be preserved in the output image. Note that EXIF
   * rotation and embedded color profiles are always applied ("baked in" into
   * the image), and aren't affected by this option. Note that if the Polish
   * feature is enabled, all metadata may have been removed already and this
   * option may have no effect.
   *  - keep: Preserve most of EXIF metadata, including GPS location if there's
   *    any.
   *  - copyright: Only keep the copyright tag, and discard everything else.
   *    This is the default behavior for JPEG files.
   *  - none: Discard all invisible EXIF metadata. Currently WebP and PNG
   *    output formats always discard metadata.
   */
  metadata?: "keep" | "copyright" | "none";
  /**
   * Overlays are drawn in the order they appear in the array (last array
   * entry is the topmost layer).
   */
  draw?: RequestInitCfPropertiesImageDraw[];
  /**
   * Fetching image from authenticated origin. Setting this property will
   * pass authentication headers (Authorization, Cookie, etc.) through to
   * the origin.
   */
  "origin-auth"?: "share-publicly";
  /**
   * Slightly reduces latency on a cache miss by selecting a
   * quickest-to-compress file format, at a cost of increased file size and
   * lower image quality. It will usually override the format option and choose
   * JPEG over WebP or AVIF. We do not recommend using this option, except in
   * unusual circumstances like resizing uncacheable dynamically-generated
   * images.
   */
  compression?: "fast";

  // You probably want to add new properties to BasicImageTransformations, unless
  // you are absolutely sure they are only valid on the top level request
}

interface RequestInitCfPropertiesImageMinify {
  javascript?: boolean;
  css?: boolean;
  html?: boolean;
}

interface RequestInitCfPropertiesR2 {
  /**
   * Colo id of bucket that an object is stored in
   */
  bucketColoId?: number;
}

/**
 * Request metadata provided by Cloudflare's edge.
 */
type IncomingRequestCfProperties<HostMetadata = unknown> =
  IncomingRequestCfPropertiesBase &
    IncomingRequestCfPropertiesBotManagementEnterprise &
    IncomingRequestCfPropertiesCloudflareForSaaSEnterprise<HostMetadata> &
    IncomingRequestCfPropertiesGeographicInformation &
    IncomingRequestCfPropertiesCloudflareAccessOrApiShield;

interface IncomingRequestCfPropertiesBase extends Record<string, unknown> {
  /**
   * [ASN](https://www.iana.org/assignments/as-numbers/as-numbers.xhtml) of the incoming request.
   *
   * @example 395747
   */
  asn?: number;
  /**
   * The organization which owns the ASN of the incoming request.
   *
   * @example "Google Cloud"
   */
  asOrganization?: string;
  /**
   * The original value of the \`Accept-Encoding\` header if Cloudflare modified it.
   *
   * @example "gzip, deflate, br"
   */
  clientAcceptEncoding?: string;
  /**
   * The number of milliseconds it took for the request to reach your worker.
   *
   * @example 22
   */
  clientTcpRtt?: number;
  /**
   * The three-letter [IATA](https://en.wikipedia.org/wiki/IATA_airport_code)
   * airport code of the data center that the request hit.
   *
   * @example "DFW"
   */
  colo: string;
  /**
   * Represents the upstream's response to a
   * [TCP \`keepalive\` message](https://tldp.org/HOWTO/TCP-Keepalive-HOWTO/overview.html)
   * from cloudflare.
   *
   * For workers with no upstream, this will always be \`1\`.
   *
   * @example 3
   */
  edgeRequestKeepAliveStatus: IncomingRequestCfPropertiesEdgeRequestKeepAliveStatus;
  /**
   * The HTTP Protocol the request used.
   *
   * @example "HTTP/2"
   */
  httpProtocol: string;
  /**
   * The browser-requested prioritization information in the request object.
   *
   * If no information was set, defaults to the empty string \`""\`
   *
   * @example "weight=192;exclusive=0;group=3;group-weight=127"
   * @default ""
   */
  requestPriority: string;
  /**
   * The TLS version of the connection to Cloudflare.
   * In requests served over plaintext (without TLS), this property is the empty string \`""\`.
   *
   * @example "TLSv1.3"
   */
  tlsVersion: string;
  /**
   * The cipher for the connection to Cloudflare.
   * In requests served over plaintext (without TLS), this property is the empty string \`""\`.
   *
   * @example "AEAD-AES128-GCM-SHA256"
   */
  tlsCipher: string;
  /**
   * Metadata containing the [\`HELLO\`](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.1.2) and [\`FINISHED\`](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.9) messages from this request's TLS handshake.
   *
   * If the incoming request was served over plaintext (without TLS) this field is undefined.
   */
  tlsExportedAuthenticator?: IncomingRequestCfPropertiesExportedAuthenticatorMetadata;
}

interface IncomingRequestCfPropertiesBotManagementBase {
  /**
   * Cloudflare\u2019s [level of certainty](https://developers.cloudflare.com/bots/concepts/bot-score/) that a request comes from a bot,
   * represented as an integer percentage between \`1\` (almost certainly a bot) and \`99\` (almost certainly human).
   *
   * @example 54
   */
  score: number;
  /**
   * A boolean value that is true if the request comes from a good bot, like Google or Bing.
   * Most customers choose to allow this traffic. For more details, see [Traffic from known bots](https://developers.cloudflare.com/firewall/known-issues-and-faq/#how-does-firewall-rules-handle-traffic-from-known-bots).
   */
  verifiedBot: boolean;
  /**
   * A boolean value that is true if the request originates from a
   * Cloudflare-verified proxy service.
   */
  corporateProxy: boolean;
  /**
   * A boolean value that's true if the request matches [file extensions](https://developers.cloudflare.com/bots/reference/static-resources/) for many types of static resources.
   */
  staticResource: boolean;
  /**
   * List of IDs that correlate to the Bot Management heuristic detections made on a request (you can have multiple heuristic detections on the same request).
   */
  detectionIds: number[];
}

interface IncomingRequestCfPropertiesBotManagement {
  /**
   * Results of Cloudflare's Bot Management analysis
   */
  botManagement: IncomingRequestCfPropertiesBotManagementBase;
  /**
   * Duplicate of \`botManagement.score\`.
   *
   * @deprecated
   */
  clientTrustScore: number;
}

interface IncomingRequestCfPropertiesBotManagementEnterprise
  extends IncomingRequestCfPropertiesBotManagement {
  /**
   * Results of Cloudflare's Bot Management analysis
   */
  botManagement: IncomingRequestCfPropertiesBotManagementBase & {
    /**
     * A [JA3 Fingerprint](https://developers.cloudflare.com/bots/concepts/ja3-fingerprint/) to help profile specific SSL/TLS clients
     * across different destination IPs, Ports, and X509 certificates.
     */
    ja3Hash: string;
  };
}

interface IncomingRequestCfPropertiesCloudflareForSaaSEnterprise<HostMetadata> {
  /**
   * Custom metadata set per-host in [Cloudflare for SaaS](https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/).
   *
   * This field is only present if you have Cloudflare for SaaS enabled on your account
   * and you have followed the [required steps to enable it]((https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/domain-support/custom-metadata/)).
   */
  hostMetadata?: HostMetadata;
}

interface IncomingRequestCfPropertiesCloudflareAccessOrApiShield {
  /**
   * Information about the client certificate presented to Cloudflare.
   *
   * This is populated when the incoming request is served over TLS using
   * either Cloudflare Access or API Shield (mTLS)
   * and the presented SSL certificate has a valid
   * [Certificate Serial Number](https://ldapwiki.com/wiki/Certificate%20Serial%20Number)
   * (i.e., not \`null\` or \`""\`).
   *
   * Otherwise, a set of placeholder values are used.
   *
   * The property \`certPresented\` will be set to \`"1"\` when
   * the object is populated (i.e. the above conditions were met).
   */
  tlsClientAuth:
    | IncomingRequestCfPropertiesTLSClientAuth
    | IncomingRequestCfPropertiesTLSClientAuthPlaceholder;
}

/**
 * Metadata about the request's TLS handshake
 */
interface IncomingRequestCfPropertiesExportedAuthenticatorMetadata {
  /**
   * The client's [\`HELLO\` message](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.1.2), encoded in hexadecimal
   *
   * @example "44372ba35fa1270921d318f34c12f155dc87b682cf36a790cfaa3ba8737a1b5d"
   */
  clientHandshake: string;
  /**
   * The server's [\`HELLO\` message](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.1.2), encoded in hexadecimal
   *
   * @example "44372ba35fa1270921d318f34c12f155dc87b682cf36a790cfaa3ba8737a1b5d"
   */
  serverHandshake: string;
  /**
   * The client's [\`FINISHED\` message](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.9), encoded in hexadecimal
   *
   * @example "084ee802fe1348f688220e2a6040a05b2199a761f33cf753abb1b006792d3f8b"
   */
  clientFinished: string;
  /**
   * The server's [\`FINISHED\` message](https://www.rfc-editor.org/rfc/rfc5246#section-7.4.9), encoded in hexadecimal
   *
   * @example "084ee802fe1348f688220e2a6040a05b2199a761f33cf753abb1b006792d3f8b"
   */
  serverFinished: string;
}

/**
 * Geographic data about the request's origin.
 */
interface IncomingRequestCfPropertiesGeographicInformation {
  /**
   * The [ISO 3166-1 Alpha 2](https://www.iso.org/iso-3166-country-codes.html) country code the request originated from.
   *
   * If your worker is [configured to accept TOR connections](https://support.cloudflare.com/hc/en-us/articles/203306930-Understanding-Cloudflare-Tor-support-and-Onion-Routing), this may also be \`"T1"\`, indicating a request that originated over TOR.
   *
   * If Cloudflare is unable to determine where the request originated this property is omitted.
   *
   * The country code \`"T1"\` is used for requests originating on TOR.
   *
   * @example "GB"
   */
  country?: Iso3166Alpha2Code | "T1";
  /**
   * If present, this property indicates that the request originated in the EU
   *
   * @example "1"
   */
  isEUCountry?: "1";
  /**
   * A two-letter code indicating the continent the request originated from.
   *
   * @example "AN"
   */
  continent?: ContinentCode;
  /**
   * The city the request originated from
   *
   * @example "Austin"
   */
  city?: string;
  /**
   * Postal code of the incoming request
   *
   * @example "78701"
   */
  postalCode?: string;
  /**
   * Latitude of the incoming request
   *
   * @example "30.27130"
   */
  latitude?: string;
  /**
   * Longitude of the incoming request
   *
   * @example "-97.74260"
   */
  longitude?: string;
  /**
   * Timezone of the incoming request
   *
   * @example "America/Chicago"
   */
  timezone?: string;
  /**
   * If known, the ISO 3166-2 name for the first level region associated with
   * the IP address of the incoming request
   *
   * @example "Texas"
   */
  region?: string;
  /**
   * If known, the ISO 3166-2 code for the first-level region associated with
   * the IP address of the incoming request
   *
   * @example "TX"
   */
  regionCode?: string;
  /**
   * Metro code (DMA) of the incoming request
   *
   * @example "635"
   */
  metroCode?: string;
}

/** Data about the incoming request's TLS certificate */
interface IncomingRequestCfPropertiesTLSClientAuth {
  /** Always \`"1"\`, indicating that the certificate was presented */
  certPresented: "1";
  /**
   * Result of certificate verification.
   *
   * @example "FAILED:self signed certificate"
   */
  certVerified: Exclude<CertVerificationStatus, "NONE">;
  /** The presented certificate's revokation status.
   *
   * - A value of \`"1"\` indicates the certificate has been revoked
   * - A value of \`"0"\` indicates the certificate has not been revoked
   */
  certRevoked: "1" | "0";
  /**
   * The certificate issuer's [distinguished name](https://knowledge.digicert.com/generalinformation/INFO1745.html)
   *
   * @example "CN=cloudflareaccess.com, C=US, ST=Texas, L=Austin, O=Cloudflare"
   */
  certIssuerDN: string;
  /**
   * The certificate subject's [distinguished name](https://knowledge.digicert.com/generalinformation/INFO1745.html)
   *
   * @example "CN=*.cloudflareaccess.com, C=US, ST=Texas, L=Austin, O=Cloudflare"
   */
  certSubjectDN: string;
  /**
   * The certificate issuer's [distinguished name](https://knowledge.digicert.com/generalinformation/INFO1745.html) ([RFC 2253](https://www.rfc-editor.org/rfc/rfc2253.html) formatted)
   *
   * @example "CN=cloudflareaccess.com, C=US, ST=Texas, L=Austin, O=Cloudflare"
   */
  certIssuerDNRFC2253: string;
  /**
   * The certificate subject's [distinguished name](https://knowledge.digicert.com/generalinformation/INFO1745.html) ([RFC 2253](https://www.rfc-editor.org/rfc/rfc2253.html) formatted)
   *
   * @example "CN=*.cloudflareaccess.com, C=US, ST=Texas, L=Austin, O=Cloudflare"
   */
  certSubjectDNRFC2253: string;
  /** The certificate issuer's distinguished name (legacy policies) */
  certIssuerDNLegacy: string;
  /** The certificate subject's distinguished name (legacy policies) */
  certSubjectDNLegacy: string;
  /**
   * The certificate's serial number
   *
   * @example "00936EACBE07F201DF"
   */
  certSerial: string;
  /**
   * The certificate issuer's serial number
   *
   * @example "2489002934BDFEA34"
   */
  certIssuerSerial: string;
  /**
   * The certificate's Subject Key Identifier
   *
   * @example "BB:AF:7E:02:3D:FA:A6:F1:3C:84:8E:AD:EE:38:98:EC:D9:32:32:D4"
   */
  certSKI: string;
  /**
   * The certificate issuer's Subject Key Identifier
   *
   * @example "BB:AF:7E:02:3D:FA:A6:F1:3C:84:8E:AD:EE:38:98:EC:D9:32:32:D4"
   */
  certIssuerSKI: string;
  /**
   * The certificate's SHA-1 fingerprint
   *
   * @example "6b9109f323999e52259cda7373ff0b4d26bd232e"
   */
  certFingerprintSHA1: string;
  /**
   * The certificate's SHA-256 fingerprint
   *
   * @example "acf77cf37b4156a2708e34c4eb755f9b5dbbe5ebb55adfec8f11493438d19e6ad3f157f81fa3b98278453d5652b0c1fd1d71e5695ae4d709803a4d3f39de9dea"
   */
  certFingerprintSHA256: string;
  /**
   * The effective starting date of the certificate
   *
   * @example "Dec 22 19:39:00 2018 GMT"
   */
  certNotBefore: string;
  /**
   * The effective expiration date of the certificate
   *
   * @example "Dec 22 19:39:00 2018 GMT"
   */
  certNotAfter: string;
  /**
   * The client leaf certificate in [RFC 9440](https://www.rfc-editor.org/rfc/rfc9440)
   * format (\`:base64-DER:\`). Empty if no client certificate was presented or if
   * the leaf certificate exceeded 10 KB (see {@link certRFC9440TooLarge}).
   *
   * Suitable for forwarding to an origin via the \`Client-Cert\` HTTP header.
   */
  certRFC9440: string;
  /**
   * \`true\` if the leaf certificate exceeded 10 KB and was omitted from
   * {@link certRFC9440}.
   */
  certRFC9440TooLarge: boolean;
  /**
   * The intermediate certificate chain in [RFC 9440](https://www.rfc-editor.org/rfc/rfc9440)
   * format as a comma-separated list. Empty if no intermediates were sent or
   * if the chain exceeded 16 KB (see {@link certChainRFC9440TooLarge}).
   *
   * Suitable for forwarding to an origin via the \`Client-Cert-Chain\` HTTP header.
   */
  certChainRFC9440: string;
  /**
   * \`true\` if the intermediate chain exceeded 16 KB and was omitted from
   * {@link certChainRFC9440}.
   */
  certChainRFC9440TooLarge: boolean;
}

/** Placeholder values for TLS Client Authorization */
interface IncomingRequestCfPropertiesTLSClientAuthPlaceholder {
  certPresented: "0";
  certVerified: "NONE";
  certRevoked: "0";
  certIssuerDN: "";
  certSubjectDN: "";
  certIssuerDNRFC2253: "";
  certSubjectDNRFC2253: "";
  certIssuerDNLegacy: "";
  certSubjectDNLegacy: "";
  certSerial: "";
  certIssuerSerial: "";
  certSKI: "";
  certIssuerSKI: "";
  certFingerprintSHA1: "";
  certFingerprintSHA256: "";
  certNotBefore: "";
  certNotAfter: "";
  certRFC9440: "";
  certRFC9440TooLarge: false;
  certChainRFC9440: "";
  certChainRFC9440TooLarge: false;
}

/** Possible outcomes of TLS verification */
declare type CertVerificationStatus =
  /** Authentication succeeded */
  | "SUCCESS"
  /** No certificate was presented */
  | "NONE"
  /** Failed because the certificate was self-signed */
  | "FAILED:self signed certificate"
  /** Failed because the certificate failed a trust chain check */
  | "FAILED:unable to verify the first certificate"
  /** Failed because the certificate not yet valid */
  | "FAILED:certificate is not yet valid"
  /** Failed because the certificate is expired */
  | "FAILED:certificate has expired"
  /** Failed for another unspecified reason */
  | "FAILED";

/**
 * An upstream endpoint's response to a TCP \`keepalive\` message from Cloudflare.
 */
declare type IncomingRequestCfPropertiesEdgeRequestKeepAliveStatus =
  | 0 /** Unknown */
  | 1 /** no keepalives (not found) */
  | 2 /** no connection re-use, opening keepalive connection failed */
  | 3 /** no connection re-use, keepalive accepted and saved */
  | 4 /** connection re-use, refused by the origin server (\`TCP FIN\`) */
  | 5; /** connection re-use, accepted by the origin server */

